import importlib.util

from aaaag.paths import REPO_ROOT

spec = importlib.util.spec_from_file_location("policy", REPO_ROOT / "scripts" / "policy.py")
policy = importlib.util.module_from_spec(spec)
spec.loader.exec_module(policy)


def test_attribution_lines_are_caught():
    for message in (
        "feat: x\n\nCo-authored-by: Claude <noreply@anthropic.com>",
        "fix: y\n\nco-authored-by: someone <a@b.c>",
        "docs: z\n\n\U0001f916 Generated with [Claude Code](https://claude.com/claude-code)",
        "chore: w\n\nGenerated by Cursor",
        "feat: v\n\nAssisted-by: GPT-5 via OpenAI",
    ):
        assert policy.attribution_problems(message), message


def test_normal_messages_pass():
    for message in (
        "fix(io): handle NaN rows in the ATD fast path (#12)",
        "docs: labels are generated by the decoder, not by hand",
        "feat(decoding): HSMM with duration priors from IDSSE",
    ):
        assert not policy.attribution_problems(message), message


def test_data_paths_are_blocked():
    for path in (
        "data/tactical/BAR-ATH_tactical_atd.txt",
        "data/tactical/BAR-ATH_tactical.mp4",
        "somewhere/BAR-ATH_tactical_smart_tagging.xml",
        "cache/BAR-ATH/tracking-v2.npz",
        "outputs/submissions/x.csv",
        "AAAAG.csv",
        "analysis/notebooks/look.ipynb",
        "evaluation/gt/BAR-ATH_possession_gt.csv",
    ):
        assert policy.path_problems(path), path
    assert policy.path_problems("analysis/dump.csv", csv_lines=199_320)
    assert policy.path_problems("models/huge.txt", size=50_000_000)


def test_normal_paths_pass():
    for path in (
        "data/README.md",
        "src/aaaag/io/atd.py",
        "experiments/ameya/x.json",
        "docs/STRATEGY.md",
    ):
        assert not policy.path_problems(path, size=10_000), path
    assert not policy.path_problems(
        "vendor/mtah2027/evaluation/results/baseline_raw.csv", csv_lines=199_320
    )


def test_commit_subjects_follow_conventional_commits():
    for good in (
        "feat(decoding): HSMM with duration priors (#14)",
        "fix: off-by-one at the period boundary",
        "analysis(ballstate): ball-out signature around set pieces",
        'Revert "feat(io): faster parser"',
    ):
        assert not policy.subject_problems(good), good
    for bad in (
        "fixed stuff",
        "Feat: capitalised type",
        "feat:missing space",
        "feat: " + "x" * 120,
    ):
        assert policy.subject_problems(bad), bad


def test_secrets_and_transcripts_are_blocked():
    assert policy.secret_problems(b"token = ghp_" + b"a" * 36)
    assert policy.secret_problems(b"-----BEGIN " + b"OPENSSH PRIVATE KEY-----")
    assert not policy.secret_problems(b"spell_f1_mean = 0.4242")
    assert policy.path_problems("notes/session-2026-10-28.jsonl")


def test_handover_names_are_recognised():
    from aaaag.team import HANDOVER_NAME

    assert HANDOVER_NAME.match("2026-10-27_1922Z_ameya_repository-setup.md")
    for name in ("README.md", "_TEMPLATE.md", "notes.md"):
        assert not HANDOVER_NAME.match(name)
